public class S_HandshakeResult : IPacket // S_HandshakeResult 패킷
{
    // 멤버 변수들
    public bool ok;
	public ushort serverVersion;
	public string reason;
    public ushort Protocol { get { return (ushort)PacketID.S_HandshakeResult; } }

    public void Read(ArraySegment<byte> segment)
    {
        // segment = [size:2][id:2][payload...] 통째.
        // PacketSession이 이미 size 헤더 검증 후 한 패킷 단위로 넘김.
        ushort count = 0;
        ReadOnlySpan<byte> s = new ReadOnlySpan<byte>(segment.Array, segment.Offset, segment.Count);

        count += sizeof(ushort); // size 헤더 skip
        count += sizeof(ushort); // packet id 헤더 skip

        // 멤버 읽기
        // ok 읽기 (1바이트, 0 = false / 그 외 = true)
		this.ok = s[count] != 0;
		count += sizeof(bool);
		
		// serverVersion 읽기 (LittleEndian 명시 — wire format 약속)
		this.serverVersion = BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(count, s.Length - count));
		count += sizeof(ushort);
		
		// reason 문자열 읽기 (Length prefix UInt16 LittleEndian + UTF-16 payload)
		ushort reasonLen = BinaryPrimitives.ReadUInt16LittleEndian(s.Slice(count, s.Length - count));
		count += sizeof(ushort);
		this.reason = Encoding.Unicode.GetString(s.Slice(count, reasonLen));
		count += reasonLen;
		
    }


    public ArraySegment<byte> Write()
    {
        // SendBufferHelper 의존 X — 새 byte[] 직접 할당 후 반환.
        // 호출자(서버 GameSession / Unity UnityClientSession)가 자기 SendBuffer로 marshalling.
        // BinaryPrimitives.*LittleEndian 명시 (BitConverter는 호스트 endian 의존).
        byte[] segment = new byte[ushort.MaxValue];
        ushort count = 0;
        bool success = true;
        Span<byte> s = new Span<byte>(segment);

        count += sizeof(ushort); // size 자리 예약 (마지막에 채움)

        success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s.Slice(count, s.Length - count), (ushort)PacketID.S_HandshakeResult);
        count += sizeof(ushort);

        // 멤버 쓰기
        // ok 쓰기 (1바이트, false → 0 / true → 1)
		s[count] = (byte)(this.ok ? 1 : 0);
		count += sizeof(bool);
		
		// serverVersion 쓰기 (LittleEndian 명시 — wire format 약속)
		success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s.Slice(count, s.Length - count), this.serverVersion);
		count += sizeof(ushort);
		
		// reason 문자열 쓰기 (Length prefix UInt16 LittleEndian + UTF-16 payload)
		ushort reasonLen = (ushort)Encoding.Unicode.GetByteCount(this.reason);
		success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s.Slice(count, s.Length - count), reasonLen);
		count += sizeof(ushort);
		Encoding.Unicode.GetBytes(this.reason.AsSpan(), s.Slice(count, s.Length - count));
		count += reasonLen;
		

        // 최종 size 기록
        success &= BinaryPrimitives.TryWriteUInt16LittleEndian(s, count);

        if (!success)
            return default;

        return new ArraySegment<byte>(segment, 0, count);
    }
}

